script:
frappe.ui.form.on('Sales Invoice', {
	custom_vat_category: function(frm) {
        update_child_vat_category(frm);
    }
})


frappe.ui.form.on('Sales Invoice Item', {
    custom_vat_category: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (row.custom_vat_category) {
            frappe.db.get_value('VAT Category', row.custom_vat_category, 'item_tax_template', (data) => {
                if (data && data.item_tax_template) {
                    frappe.model.set_value(cdt, cdn, 'item_tax_template', data.item_tax_template);
                }
            });
        }
    },

    item_code: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];
        if (frm.doc.custom_vat_category) {
            frappe.model.set_value(cdt, cdn, 'custom_vat_category', frm.doc.custom_vat_category);
        }else {
            frappe.db.get_value('Item', row.item_code, 'custom_output_vat_category', (data) => {
                if (data && data.custom_output_vat_category) {
                    frappe.model.set_value(cdt, cdn, 'custom_vat_category', data.custom_output_vat_category);
                }
            });

        }
    }
});

